CREATE VIEW public.v_billing_dashboard WITH (security_invoker=true) AS  SELECT c.id AS contract_id,
    c.contract_number,
    i.name AS ies_name,
    i.tier,
    c.package_code,
    c.status AS contract_status,
    c.student_count,
    c.monthly_value,
    c.discount_percent,
    c.is_courtesy,
    c.courtesy_reason,
    c.custom_monthly,
    c.starts_at,
    c.trial_ends_at,
    c.min_commitment_ends_at,
    c.cancellation_effective_at,
    COALESCE(paid.total_paid, 0::numeric) AS total_paid,
    COALESCE(pending.total_pending, 0::numeric) AS total_pending,
    COALESCE(overdue.total_overdue, 0::numeric) AS total_overdue,
    last_inv.invoice_number AS last_invoice,
    last_inv.status AS last_invoice_status,
    last_inv.due_date AS last_invoice_due
   FROM vertice_contracts c
     JOIN vertice_institutions i ON i.id = c.institution_id
     LEFT JOIN LATERAL ( SELECT sum(inv.total) AS total_paid
           FROM vertice_invoices inv
          WHERE inv.contract_id = c.id AND inv.status = 'paid'::text) paid ON true
     LEFT JOIN LATERAL ( SELECT sum(inv.total) AS total_pending
           FROM vertice_invoices inv
          WHERE inv.contract_id = c.id AND inv.status = 'pending'::text) pending ON true
     LEFT JOIN LATERAL ( SELECT sum(inv.total) AS total_overdue
           FROM vertice_invoices inv
          WHERE inv.contract_id = c.id AND inv.status = 'overdue'::text) overdue ON true
     LEFT JOIN LATERAL ( SELECT inv.invoice_number,
            inv.status,
            inv.due_date
           FROM vertice_invoices inv
          WHERE inv.contract_id = c.id
          ORDER BY inv.issued_at DESC
         LIMIT 1) last_inv ON true;
REVOKE ALL ON public.v_billing_dashboard FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.v_billing_dashboard TO service_role;
CREATE VIEW public.v_mrr_summary WITH (security_invoker=true) AS  SELECT count(*) FILTER (WHERE status = ANY (ARRAY['active'::text, 'trial'::text, 'cancellation_pending'::text])) AS total_contracts,
    count(*) FILTER (WHERE status = 'trial'::text) AS trials,
    count(*) FILTER (WHERE status = 'active'::text) AS active,
    count(*) FILTER (WHERE status = 'cancellation_pending'::text) AS cancelling,
    sum(monthly_value) FILTER (WHERE status = 'active'::text) AS mrr_active,
    sum(monthly_value) FILTER (WHERE status = ANY (ARRAY['active'::text, 'cancellation_pending'::text])) AS mrr_total,
    sum(student_count) FILTER (WHERE status = ANY (ARRAY['active'::text, 'trial'::text])) AS total_students,
    ( SELECT sum(vertice_invoices.total) AS sum
           FROM vertice_invoices
          WHERE vertice_invoices.status = 'overdue'::text) AS total_overdue
   FROM vertice_contracts;
REVOKE ALL ON public.v_mrr_summary FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.v_mrr_summary TO service_role;
CREATE VIEW public.v_school_regulatory_context WITH (security_invoker=true) AS  SELECT i.id AS institution_id,
    i.name AS school_name,
    i.state,
    i.city,
    i.admin_dependency,
    ec.cee_name,
    ec.cee_acronym,
    ec.cee_website,
    ec.cee_legislation,
        CASE
            WHEN i.admin_dependency = 'municipal'::text THEN 'CME de '::text || COALESCE(i.city, '(município)'::text)
            ELSE ec.cee_acronym
        END AS regulatory_council,
        CASE
            WHEN i.admin_dependency = 'municipal'::text THEN 'Conselho Municipal de Educação'::text
            ELSE ec.cee_name
        END AS regulatory_council_full
   FROM vertice_institutions i
     LEFT JOIN vertice_education_councils ec ON ec.uf::text = i.state
  WHERE i.tier = 'escolas'::text;
REVOKE ALL ON public.v_school_regulatory_context FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.v_school_regulatory_context TO service_role;
CREATE VIEW public.v_active_modules WITH (security_invoker=true) AS  SELECT a.institution_id,
    a.module_code,
    c.name AS module_name,
    c.tier,
    c.package,
    c.tabs,
    a.status,
    a.package_origin,
    a.activated_at,
    a.trial_ends_at,
        CASE
            WHEN a.status = 'trial'::text AND a.trial_ends_at < now() THEN 'expirado'::text
            ELSE a.status
        END AS effective_status
   FROM vertice_module_activations a
     JOIN vertice_module_catalog c ON c.code = a.module_code
  WHERE a.status = ANY (ARRAY['ativo'::text, 'trial'::text]);
