CREATE OR REPLACE FUNCTION public.start_module_tasting(p_institution_id uuid, p_module_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_mod RECORD;
  v_existing RECORD;
  v_contract RECORD;
  v_addon_fee numeric;
BEGIN
  -- Buscar módulo no catálogo
  SELECT * INTO v_mod FROM vertice_module_catalog WHERE code = p_module_code AND active = true;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Módulo não encontrado'); END IF;

  -- Checar se já tem ativação ativa ou em degustação
  SELECT * INTO v_existing FROM vertice_module_activations 
  WHERE institution_id = p_institution_id AND module_code = p_module_code AND status IN ('ativo','trial');
  IF FOUND THEN RETURN jsonb_build_object('error', 'Módulo já ativo ou em degustação'); END IF;

  -- Buscar contrato ativo da IES
  SELECT * INTO v_contract FROM vertice_contracts 
  WHERE institution_id = p_institution_id AND status IN ('active','trial') 
  ORDER BY created_at DESC LIMIT 1;

  -- Definir fee mensal do addon baseado no tier
  v_addon_fee := CASE v_mod.tier
    WHEN 'core' THEN 500
    WHEN 'regulacao' THEN 800
    WHEN 'gestao' THEN 1000
    WHEN 'avancado' THEN 1500
    WHEN 'addon' THEN 2000
    ELSE 1000
  END;

  -- Criar ativação em modo degustação
  INSERT INTO vertice_module_activations (
    institution_id, module_code, status, package_origin,
    trial_days, trial_started_at, trial_ends_at, auto_activate, addon_monthly_fee
  ) VALUES (
    p_institution_id, p_module_code, 'trial', 'degustacao',
    15, CURRENT_DATE, CURRENT_DATE + 15, true, v_addon_fee
  );

  -- Se existe contrato, registrar no contract_addons como pendente
  IF v_contract.id IS NOT NULL THEN
    INSERT INTO vertice_contract_addons (
      contract_id, module_code, activation_fee, monthly_fee, status
    ) VALUES (
      v_contract.id, p_module_code, 0, v_addon_fee, 'active'
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'module', v_mod.name,
    'tasting_ends', CURRENT_DATE + 15,
    'monthly_fee_after', v_addon_fee,
    'auto_activate', true,
    'message', 'Degustação ativada! Você tem 15 dias para explorar o módulo ' || v_mod.name || '. Após esse período, será ativado automaticamente por R$ ' || v_addon_fee || '/mês no próximo ciclo de faturamento. Cancele a qualquer momento durante a degustação.'
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.start_module_tasting(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.start_module_tasting(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.request_downgrade(p_contract_id uuid, p_new_package text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_contract vertice_contracts%ROWTYPE;
  v_pkg_order jsonb := '{"essencial":1,"regulacao":2,"gestao360":3,"completo":4}'::jsonb;
  v_effective_date date;
BEGIN
  SELECT * INTO v_contract FROM vertice_contracts WHERE id = p_contract_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Contrato não encontrado');
  END IF;

  -- Verificar se é realmente downgrade
  IF (v_pkg_order->>p_new_package)::int >= (v_pkg_order->>v_contract.package_code)::int THEN
    RETURN jsonb_build_object('error', 'Não é downgrade. Use upgrade.');
  END IF;

  -- Verificar carência de 90 dias
  IF CURRENT_DATE < v_contract.min_commitment_ends_at THEN
    RETURN jsonb_build_object(
      'error', 'Carência mínima não atingida',
      'min_commitment_ends_at', v_contract.min_commitment_ends_at,
      'days_remaining', v_contract.min_commitment_ends_at - CURRENT_DATE,
      'message', 'Downgrade disponível a partir de ' || v_contract.min_commitment_ends_at
    );
  END IF;

  -- Downgrade no próximo ciclo
  v_effective_date := (date_trunc('month', CURRENT_DATE) + INTERVAL '1 month')::date;

  INSERT INTO vertice_contract_changes (
    contract_id, change_type, from_value, to_value,
    effective_at, min_commitment_check
  ) VALUES (
    p_contract_id, 'downgrade',
    jsonb_build_object('package', v_contract.package_code),
    jsonb_build_object('package', p_new_package),
    v_effective_date, true
  );

  RETURN jsonb_build_object(
    'success', true,
    'effective_date', v_effective_date,
    'from_package', v_contract.package_code,
    'to_package', p_new_package,
    'message', 'Downgrade agendado para ' || v_effective_date || '. Pacote atual mantido até lá.'
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.request_downgrade(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.request_downgrade(uuid,text) TO service_role;
