CREATE OR REPLACE FUNCTION public.create_contract(p_institution_id uuid, p_package_code text, p_price_per_student numeric, p_min_monthly numeric, p_max_monthly numeric DEFAULT NULL::numeric, p_student_count integer DEFAULT 0, p_implementation_fee numeric DEFAULT 0, p_with_trial boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_contract_id uuid;
  v_contract_number text;
  v_starts date := CURRENT_DATE;
  v_trial_ends date;
  v_cooling_off date;
  v_min_commitment date;
  v_status text;
BEGIN
  -- Gerar número do contrato: VRT-YYYYMM-XXXX
  SELECT 'VRT-' || to_char(now(), 'YYYYMM') || '-' || 
         lpad((COALESCE(MAX(CAST(split_part(contract_number, '-', 3) AS integer)), 0) + 1)::text, 4, '0')
  INTO v_contract_number
  FROM vertice_contracts
  WHERE contract_number LIKE 'VRT-' || to_char(now(), 'YYYYMM') || '-%';

  IF p_with_trial THEN
    v_trial_ends := v_starts + INTERVAL '90 days';
    v_status := 'trial';
  ELSE
    v_status := 'active';
  END IF;

  v_cooling_off := v_starts + INTERVAL '7 days';
  v_min_commitment := v_starts + INTERVAL '90 days';

  INSERT INTO vertice_contracts (
    institution_id, package_code, price_per_student, min_monthly, max_monthly,
    student_count, implementation_fee, starts_at, trial_ends_at,
    cooling_off_expires_at, min_commitment_ends_at, status, contract_number, signed_at
  ) VALUES (
    p_institution_id, p_package_code, p_price_per_student, p_min_monthly, p_max_monthly,
    p_student_count, p_implementation_fee, v_starts, v_trial_ends,
    v_cooling_off, v_min_commitment, v_status, v_contract_number, now()
  )
  RETURNING id INTO v_contract_id;

  -- Ativar módulos do pacote
  PERFORM activate_package(p_institution_id, p_package_code, v_status, 
    CASE WHEN p_with_trial THEN 90 ELSE NULL END);

  -- Se tem implementação, gerar fatura de implementação (cobrada mesmo no trial)
  IF p_implementation_fee > 0 THEN
    INSERT INTO vertice_invoices (
      contract_id, institution_id, invoice_number, invoice_type,
      subtotal, total, due_date, status, line_items
    ) VALUES (
      v_contract_id, p_institution_id,
      'IMP-' || v_contract_number,
      'implementacao',
      p_implementation_fee, p_implementation_fee,
      CURRENT_DATE + INTERVAL '5 days',
      'pending',
      jsonb_build_array(jsonb_build_object(
        'description', 'Taxa de implementação — Pacote ' || initcap(p_package_code),
        'amount', p_implementation_fee
      ))
    );
  END IF;

  RETURN jsonb_build_object(
    'contract_id', v_contract_id,
    'contract_number', v_contract_number,
    'status', v_status,
    'trial_ends_at', v_trial_ends,
    'cooling_off_expires_at', v_cooling_off,
    'min_commitment_ends_at', v_min_commitment,
    'monthly_value_after_trial', GREATEST(p_min_monthly, p_price_per_student * p_student_count)
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.create_contract(uuid,text,numeric,numeric,numeric,integer,numeric,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_contract(uuid,text,numeric,numeric,numeric,integer,numeric,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.billing_daily_cron()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_overdue integer;
  v_tastings jsonb;
  v_cycles jsonb;
  v_ref_month date := date_trunc('month', CURRENT_DATE)::date;
BEGIN
  -- 1. Marcar faturas vencidas e suspender contratos inadimplentes (30+ dias)
  v_overdue := mark_overdue_invoices();

  -- 2. Converter degustações expiradas em ativações pagas
  v_tastings := convert_expired_tastings();

  -- 3. Gerar ciclos de faturamento do mês (só no dia 1 ou se não existem ainda)
  v_cycles := generate_billing_cycle(v_ref_month);

  -- 4. Expirar cortesias vencidas
  UPDATE vertice_contracts SET
    is_courtesy = false,
    updated_at = now(),
    negotiation_notes = COALESCE(negotiation_notes, '') || E'\n[AUTO] Cortesia expirada em ' || CURRENT_DATE
  WHERE is_courtesy = true AND courtesy_expires_at IS NOT NULL AND courtesy_expires_at < CURRENT_DATE;

  RETURN jsonb_build_object(
    'executed_at', now(),
    'overdue_marked', v_overdue,
    'tastings_converted', v_tastings,
    'billing_cycles', v_cycles
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.billing_daily_cron() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.billing_daily_cron() TO service_role;
CREATE OR REPLACE FUNCTION public.sign_contract_digitally(p_contract_id uuid, p_signer_name text, p_signer_email text, p_signer_cpf text, p_signer_role text, p_ip_address inet, p_user_agent text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_contract vertice_contracts%ROWTYPE;
  v_terms vertice_contract_terms%ROWTYPE;
  v_snapshot jsonb;
  v_hash text;
  v_sig_id uuid;
  v_token text;
BEGIN
  SELECT * INTO v_contract FROM vertice_contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Contrato não encontrado'); END IF;

  SELECT * INTO v_terms FROM vertice_contract_terms WHERE is_active = true ORDER BY published_at DESC LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Termos não publicados'); END IF;

  -- Snapshot: estado exato do contrato + termos no momento do aceite
  v_snapshot := jsonb_build_object(
    'contract', jsonb_build_object(
      'id', v_contract.id,
      'contract_number', v_contract.contract_number,
      'package_code', v_contract.package_code,
      'price_per_student', v_contract.price_per_student,
      'min_monthly', v_contract.min_monthly,
      'max_monthly', v_contract.max_monthly,
      'student_count', v_contract.student_count,
      'implementation_fee', v_contract.implementation_fee,
      'starts_at', v_contract.starts_at,
      'trial_ends_at', v_contract.trial_ends_at,
      'min_commitment_ends_at', v_contract.min_commitment_ends_at
    ),
    'terms_version', v_terms.version,
    'billing_entity', v_terms.billing_entity_name,
    'signed_at', now()
  );

  -- Hash SHA-256 do snapshot (prova de integridade)
  v_hash := encode(digest(v_snapshot::text, 'sha256'), 'hex');

  -- Token de confirmação por e-mail
  v_token := encode(gen_random_bytes(32), 'hex');

  INSERT INTO vertice_contract_signatures (
    contract_id, terms_id, institution_id,
    signer_name, signer_email, signer_cpf, signer_role,
    ip_address, user_agent, document_hash, document_snapshot,
    confirmation_token
  ) VALUES (
    p_contract_id, v_terms.id, v_contract.institution_id,
    p_signer_name, p_signer_email, p_signer_cpf, p_signer_role,
    p_ip_address, p_user_agent, v_hash, v_snapshot,
    v_token
  ) RETURNING id INTO v_sig_id;

  -- Atualizar contrato como assinado
  UPDATE vertice_contracts SET signed_at = now(), updated_at = now()
  WHERE id = p_contract_id AND signed_at IS NULL;

  -- Criar consentimentos LGPD padrão
  INSERT INTO vertice_lgpd_consents (institution_id, contract_id, consent_type, granted_by, legal_basis, purpose, data_categories)
  VALUES
    (v_contract.institution_id, p_contract_id, 'data_processing', p_signer_name, 'Art. 7º, V — Execução de contrato', 'Operação da Plataforma Vértice', ARRAY['cadastrais','acadêmicos','institucionais']),
    (v_contract.institution_id, p_contract_id, 'data_sharing_mec', p_signer_name, 'Art. 7º, II — Obrigação legal', 'Atendimento a exigências MEC/INEP/CAPES', ARRAY['acadêmicos','regulatórios']),
    (v_contract.institution_id, p_contract_id, 'student_data', p_signer_name, 'Art. 7º, V — Execução de contrato', 'Gestão acadêmica e acompanhamento discente', ARRAY['cadastrais','acadêmicos','inclusão']),
    (v_contract.institution_id, p_contract_id, 'faculty_data', p_signer_name, 'Art. 7º, V — Execução de contrato', 'Gestão docente e compliance regulatório', ARRAY['profissionais','vínculo','produção_acadêmica']),
    (v_contract.institution_id, p_contract_id, 'analytics', p_signer_name, 'Art. 7º, IX — Legítimo interesse', 'Business Intelligence e indicadores de gestão', ARRAY['acadêmicos','institucionais']),
    (v_contract.institution_id, p_contract_id, 'subprocessor', p_signer_name, 'Art. 7º, V — Execução de contrato', 'Subprocessadores: Supabase (BD), Render (hospedagem)', ARRAY['todos_os_dados_tratados']);

  RETURN jsonb_build_object(
    'success', true,
    'signature_id', v_sig_id,
    'document_hash', v_hash,
    'terms_version', v_terms.version,
    'confirmation_token', v_token,
    'message', 'Contrato assinado digitalmente. Confirmação por e-mail pendente.',
    'legal_notice', 'Assinatura eletrônica simples nos termos da Lei 14.063/2020, art. 4º, I. Registro: IP ' || p_ip_address || ' em ' || now()
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.sign_contract_digitally(uuid,text,text,text,text,inet,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sign_contract_digitally(uuid,text,text,text,text,inet,text) TO service_role;
CREATE OR REPLACE FUNCTION public.activate_package(p_institution_id uuid, p_package text, p_status text DEFAULT 'ativo'::text, p_trial_days integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_count int := 0;
  v_trial_end timestamptz := CASE WHEN p_trial_days IS NOT NULL THEN now() + (p_trial_days || ' days')::interval ELSE NULL END;
  r record;
BEGIN
  FOR r IN SELECT code FROM vertice_module_catalog 
    WHERE package = p_package OR package = 'essencial' 
    ORDER BY display_order
  LOOP
    INSERT INTO vertice_module_activations (institution_id, module_code, status, package_origin, trial_ends_at)
    VALUES (p_institution_id, r.code, p_status, p_package, v_trial_end)
    ON CONFLICT (institution_id, module_code) DO UPDATE SET
      status = EXCLUDED.status,
      package_origin = EXCLUDED.package_origin,
      trial_ends_at = EXCLUDED.trial_ends_at;
    v_count := v_count + 1;
  END LOOP;
  -- Se pacote >= regulacao, inclui regulacao
  IF p_package IN ('regulacao','gestao360','completo') THEN
    FOR r IN SELECT code FROM vertice_module_catalog WHERE package = 'regulacao' LOOP
      INSERT INTO vertice_module_activations (institution_id, module_code, status, package_origin, trial_ends_at)
      VALUES (p_institution_id, r.code, p_status, p_package, v_trial_end)
      ON CONFLICT (institution_id, module_code) DO UPDATE SET status = EXCLUDED.status, package_origin = EXCLUDED.package_origin, trial_ends_at = EXCLUDED.trial_ends_at;
      v_count := v_count + 1;
    END LOOP;
  END IF;
  -- Se pacote >= gestao360, inclui gestao
  IF p_package IN ('gestao360','completo') THEN
    FOR r IN SELECT code FROM vertice_module_catalog WHERE package = 'gestao360' LOOP
      INSERT INTO vertice_module_activations (institution_id, module_code, status, package_origin, trial_ends_at)
      VALUES (p_institution_id, r.code, p_status, p_package, v_trial_end)
      ON CONFLICT (institution_id, module_code) DO UPDATE SET status = EXCLUDED.status, package_origin = EXCLUDED.package_origin, trial_ends_at = EXCLUDED.trial_ends_at;
      v_count := v_count + 1;
    END LOOP;
  END IF;
  -- Se completo, inclui tudo
  IF p_package = 'completo' THEN
    FOR r IN SELECT code FROM vertice_module_catalog WHERE package IN ('completo','addon') LOOP
      INSERT INTO vertice_module_activations (institution_id, module_code, status, package_origin, trial_ends_at)
      VALUES (p_institution_id, r.code, p_status, p_package, v_trial_end)
      ON CONFLICT (institution_id, module_code) DO UPDATE SET status = EXCLUDED.status, package_origin = EXCLUDED.package_origin, trial_ends_at = EXCLUDED.trial_ends_at;
      v_count := v_count + 1;
    END LOOP;
  END IF;
  RETURN v_count;
END; $function$
;
REVOKE ALL ON FUNCTION public.activate_package(uuid,text,text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.activate_package(uuid,text,text,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.mark_overdue_invoices()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_count integer;
BEGIN
  UPDATE vertice_invoices SET status = 'overdue', updated_at = now()
  WHERE status = 'pending' AND due_date < CURRENT_DATE;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  UPDATE vertice_contracts SET status = 'suspended', updated_at = now()
  WHERE id IN (
    SELECT DISTINCT contract_id FROM vertice_invoices
    WHERE status = 'overdue' AND due_date < CURRENT_DATE - INTERVAL '30 days'
  ) AND status = 'active';

  RETURN v_count;
END;
$function$
;
REVOKE ALL ON FUNCTION public.mark_overdue_invoices() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mark_overdue_invoices() TO service_role;
CREATE OR REPLACE FUNCTION public.generate_billing_cycle(p_reference_month date DEFAULT (date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_contract RECORD;
  v_cycle_id uuid;
  v_invoice_number text;
  v_addons_total numeric;
  v_total numeric;
  v_line_items jsonb;
  v_count integer := 0;
  v_cycle_end date;
  v_due_date date;
BEGIN
  v_cycle_end := (p_reference_month + INTERVAL '1 month - 1 day')::date;
  v_due_date := p_reference_month + INTERVAL '10 days';

  FOR v_contract IN
    SELECT c.*, i.name as ies_name
    FROM vertice_contracts c
    JOIN vertice_institutions i ON i.id = c.institution_id
    WHERE c.status IN ('active', 'trial', 'cancellation_pending')
    AND NOT EXISTS (
      SELECT 1 FROM vertice_billing_cycles bc
      WHERE bc.contract_id = c.id AND bc.cycle_start = p_reference_month
    )
  LOOP
    SELECT COALESCE(SUM(monthly_fee), 0) INTO v_addons_total
    FROM vertice_contract_addons WHERE contract_id = v_contract.id AND status = 'active';

    v_total := v_contract.monthly_value + v_addons_total;

    v_line_items := jsonb_build_array(jsonb_build_object(
      'description', 'Mensalidade Vértice — Pacote ' || initcap(v_contract.package_code),
      'students', v_contract.student_count,
      'unit_price', v_contract.price_per_student,
      'amount', v_contract.monthly_value
    ));

    SELECT v_line_items || COALESCE(jsonb_agg(jsonb_build_object(
      'description', 'Add-on: ' || ca.module_code, 'amount', ca.monthly_fee
    )), '[]'::jsonb) INTO v_line_items
    FROM vertice_contract_addons ca
    WHERE ca.contract_id = v_contract.id AND ca.status = 'active' AND ca.monthly_fee > 0;

    INSERT INTO vertice_billing_cycles (
      contract_id, institution_id, cycle_start, cycle_end, due_date,
      base_monthly, addons_total, total_amount,
      status, student_count_snapshot
    ) VALUES (
      v_contract.id, v_contract.institution_id, p_reference_month, v_cycle_end, v_due_date,
      v_contract.monthly_value, v_addons_total, v_total,
      CASE WHEN v_contract.status = 'trial' AND v_contract.trial_ends_at >= p_reference_month
           THEN 'waived' ELSE 'pending' END,
      v_contract.student_count
    ) RETURNING id INTO v_cycle_id;

    IF v_contract.status != 'trial' OR v_contract.trial_ends_at < p_reference_month THEN
      v_count := v_count + 1;
      v_invoice_number := 'VRT-' || to_char(p_reference_month, 'YYYYMM') || '-' ||
                          lpad(v_count::text, 4, '0');

      INSERT INTO vertice_invoices (
        billing_cycle_id, contract_id, institution_id,
        invoice_number, invoice_type, subtotal, total, due_date,
        status, line_items
      ) VALUES (
        v_cycle_id, v_contract.id, v_contract.institution_id,
        v_invoice_number, 'mensalidade', v_total, v_total, v_due_date,
        'pending', v_line_items
      );

      UPDATE vertice_billing_cycles SET status = 'invoiced' WHERE id = v_cycle_id;
    END IF;
  END LOOP;

  UPDATE vertice_contracts SET status = 'cancelled', updated_at = now()
  WHERE status = 'cancellation_pending' AND cancellation_effective_at <= p_reference_month;

  UPDATE vertice_contracts SET status = 'active', updated_at = now()
  WHERE status = 'trial' AND trial_ends_at < p_reference_month;

  RETURN jsonb_build_object('cycles_generated', v_count, 'reference_month', p_reference_month);
END;
$function$
;
REVOKE ALL ON FUNCTION public.generate_billing_cycle(date) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.generate_billing_cycle(date) TO service_role;
CREATE OR REPLACE FUNCTION public.register_payment(p_invoice_id uuid, p_payment_method text DEFAULT 'pix'::text, p_payment_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_invoice vertice_invoices%ROWTYPE;
BEGIN
  SELECT * INTO v_invoice FROM vertice_invoices WHERE id = p_invoice_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Fatura não encontrada');
  END IF;

  IF v_invoice.status = 'paid' THEN
    RETURN jsonb_build_object('error', 'Fatura já paga');
  END IF;

  UPDATE vertice_invoices SET
    status = 'paid',
    paid_at = now(),
    payment_method = p_payment_method,
    payment_reference = p_payment_reference,
    updated_at = now()
  WHERE id = p_invoice_id;

  UPDATE vertice_billing_cycles SET status = 'paid'
  WHERE id = v_invoice.billing_cycle_id;

  -- Se contrato estava suspenso, reativar
  UPDATE vertice_contracts SET status = 'active', updated_at = now()
  WHERE id = v_invoice.contract_id AND status = 'suspended';

  RETURN jsonb_build_object(
    'success', true,
    'invoice_number', v_invoice.invoice_number,
    'amount', v_invoice.total,
    'paid_at', now()
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.register_payment(uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.register_payment(uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.get_module_catalog_for_ies(p_institution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_agg(row_to_json(q.*) ORDER BY q.display_order) INTO v_result
  FROM (
    SELECT 
      mc.code,
      mc.name,
      mc.description,
      mc.tier,
      mc.package as min_package,
      mc.tabs,
      mc.display_order,
      COALESCE(ma.status, 'inativo') as activation_status,
      ma.trial_ends_at as tasting_ends,
      ma.addon_monthly_fee,
      ma.package_origin,
      CASE
        WHEN ma.status = 'ativo' THEN 'active'
        WHEN ma.status = 'trial' AND ma.package_origin = 'degustacao' THEN 'tasting'
        WHEN ma.status = 'trial' THEN 'trial'
        ELSE 'locked'
      END as display_status,
      CASE mc.tier
        WHEN 'core' THEN 500
        WHEN 'regulacao' THEN 800
        WHEN 'gestao' THEN 1000
        WHEN 'avancado' THEN 1500
        WHEN 'addon' THEN 2000
        ELSE 1000
      END as estimated_monthly_fee
    FROM vertice_module_catalog mc
    LEFT JOIN vertice_module_activations ma 
      ON ma.module_code = mc.code 
      AND ma.institution_id = p_institution_id
      AND ma.status IN ('ativo','trial')
    WHERE mc.active = true
  ) q;

