CREATE OR REPLACE FUNCTION public.request_cancellation(p_contract_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_contract vertice_contracts%ROWTYPE;
  v_effective_date date;
  v_is_cooling_off boolean;
  v_refund_eligible boolean := false;
BEGIN
  SELECT * INTO v_contract FROM vertice_contracts WHERE id = p_contract_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Contrato não encontrado');
  END IF;

  IF v_contract.status IN ('cancelled','expired') THEN
    RETURN jsonb_build_object('error', 'Contrato já cancelado/expirado');
  END IF;

  -- Verificar direito de arrependimento (7 dias CDC)
  v_is_cooling_off := CURRENT_DATE <= v_contract.cooling_off_expires_at;

  IF v_is_cooling_off THEN
    -- Cancelamento imediato, com reembolso integral
    v_effective_date := CURRENT_DATE;
    v_refund_eligible := true;

    UPDATE vertice_contracts SET
      status = 'cancelled',
      cancellation_requested_at = now(),
      cancellation_effective_at = v_effective_date,
      cancellation_reason = COALESCE(p_reason, 'Direito de arrependimento (7 dias CDC)'),
      updated_at = now()
    WHERE id = p_contract_id;

    -- Cancelar faturas pendentes
    UPDATE vertice_invoices SET status = 'cancelled', updated_at = now()
    WHERE contract_id = p_contract_id AND status IN ('draft','pending');

    -- Desativar módulos
    UPDATE vertice_module_activations SET status = 'cancelado'
    WHERE institution_id = v_contract.institution_id;

  ELSE
    -- Fora dos 7 dias: cancelamento ao fim do ciclo atual ou da carência
    v_effective_date := GREATEST(
      (date_trunc('month', CURRENT_DATE) + INTERVAL '1 month')::date,  -- fim do mês
      v_contract.min_commitment_ends_at  -- respeita carência de 90 dias
    );

    UPDATE vertice_contracts SET
      status = 'cancellation_pending',
      cancellation_requested_at = now(),
      cancellation_effective_at = v_effective_date,
      cancellation_reason = p_reason,
      updated_at = now()
    WHERE id = p_contract_id;
  END IF;

  -- Registrar mudança
  INSERT INTO vertice_contract_changes (
    contract_id, change_type, from_value, to_value,
    effective_at, cooling_off_eligible
  ) VALUES (
    p_contract_id, 'cancellation',
    jsonb_build_object('status', v_contract.status),
    jsonb_build_object('status', CASE WHEN v_is_cooling_off THEN 'cancelled' ELSE 'cancellation_pending' END),
    v_effective_date, v_is_cooling_off
  );

  RETURN jsonb_build_object(
    'success', true,
    'cooling_off', v_is_cooling_off,
    'effective_date', v_effective_date,
    'refund_eligible', v_refund_eligible,
    'message', CASE 
      WHEN v_is_cooling_off THEN 'Cancelamento imediato por direito de arrependimento (art. 49 CDC). Reembolso integral.'
      ELSE 'Cancelamento agendado para ' || v_effective_date || '. Faturamento continua até essa data.'
    END
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.request_cancellation(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.request_cancellation(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.cancel_module_tasting(p_institution_id uuid, p_module_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
BEGIN
  UPDATE vertice_module_activations SET status = 'cancelado'
  WHERE institution_id = p_institution_id AND module_code = p_module_code 
    AND status = 'trial' AND package_origin = 'degustacao';

  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Degustação não encontrada'); END IF;

  -- Cancelar addon pendente
  UPDATE vertice_contract_addons SET status = 'cancelled'
  WHERE module_code = p_module_code 
    AND contract_id IN (SELECT id FROM vertice_contracts WHERE institution_id = p_institution_id AND status IN ('active','trial'));

  RETURN jsonb_build_object('success', true, 'message', 'Degustação cancelada. Módulo desativado.');
END;
$function$
;
REVOKE ALL ON FUNCTION public.cancel_module_tasting(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cancel_module_tasting(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.generate_extension_code(p_institution_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_acronym text;
  v_year smallint := extract(year from now())::smallint;
  v_seq integer;
BEGIN
  -- Pegar sigla da IES
  SELECT acronym INTO v_acronym FROM vertice_institutions WHERE id = p_institution_id;
  IF v_acronym IS NULL THEN v_acronym := 'IES'; END IF;

  -- Upsert no contador e pegar o próximo valor
  INSERT INTO vertice_extension_seq (institution_id, year, next_val)
  VALUES (p_institution_id, v_year, 1)
  ON CONFLICT (institution_id, year) 
  DO UPDATE SET next_val = vertice_extension_seq.next_val + 1
  RETURNING next_val INTO v_seq;

  RETURN 'EXT-' || upper(replace(v_acronym, ' ', '')) || '-' || v_year || '-' || lpad(v_seq::text, 3, '0');
END;
$function$
;
REVOKE ALL ON FUNCTION public.generate_extension_code(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.generate_extension_code(uuid) TO service_role;
COMMIT;

