CREATE OR REPLACE FUNCTION public.confirm_contract_signature(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_sig vertice_contract_signatures%ROWTYPE;
BEGIN
  SELECT * INTO v_sig FROM vertice_contract_signatures WHERE confirmation_token = p_token;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Token inválido'); END IF;
  IF v_sig.email_confirmed_at IS NOT NULL THEN RETURN jsonb_build_object('error', 'Já confirmado'); END IF;

  UPDATE vertice_contract_signatures SET
    email_confirmed_at = now(),
    email_confirmation_sent_at = COALESCE(email_confirmation_sent_at, now())
  WHERE id = v_sig.id;

  RETURN jsonb_build_object('success', true, 'confirmed_at', now());
END;
$function$
;
