CREATE OR REPLACE FUNCTION public.convert_expired_tastings()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_count integer := 0;
  v_rec RECORD;
BEGIN
  FOR v_rec IN
    SELECT * FROM vertice_module_activations
    WHERE status = 'trial' AND package_origin = 'degustacao'
      AND trial_ends_at < CURRENT_DATE AND auto_activate = true
  LOOP
    UPDATE vertice_module_activations SET
      status = 'ativo', package_origin = 'addon_auto'
    WHERE id = v_rec.id;
    v_count := v_count + 1;
  END LOOP;

  -- Desativar quem optou por não continuar
  UPDATE vertice_module_activations SET status = 'cancelado'
  WHERE status = 'trial' AND package_origin = 'degustacao'
    AND trial_ends_at < CURRENT_DATE AND auto_activate = false;

  RETURN jsonb_build_object('converted', v_count);
END;
$function$
;
