CREATE OR REPLACE FUNCTION public.generate_doc_alerts(p_institution_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE v_count int := 0; v_partial int;
BEGIN
  -- Documentos vencidos
  INSERT INTO vertice_doc_alerts (institution_id, document_id, alert_type, severity, title, message, due_date)
  SELECT d.institution_id, d.id, 'expired', 'critical',
    'Documento vencido: ' || d.title,
    c.label || ' venceu em ' || d.expiry_date::text,
    d.expiry_date
  FROM vertice_documents d
  JOIN vertice_doc_categories c ON c.code = d.category_code
  WHERE d.institution_id = p_institution_id AND d.status = 'active' AND d.expiry_date < CURRENT_DATE
    AND NOT EXISTS (SELECT 1 FROM vertice_doc_alerts a WHERE a.document_id = d.id AND a.alert_type = 'expired' AND NOT a.acknowledged);
  GET DIAGNOSTICS v_partial = ROW_COUNT; v_count := v_count + v_partial;

  -- Vencendo em 30 dias
  INSERT INTO vertice_doc_alerts (institution_id, document_id, alert_type, severity, title, message, due_date)
  SELECT d.institution_id, d.id, 'expiring_soon',
    CASE WHEN d.expiry_date <= CURRENT_DATE + interval '7 days' THEN 'high' ELSE 'medium' END,
    'Vence em breve: ' || d.title,
    c.label || ' vence em ' || d.expiry_date::text,
    d.expiry_date
  FROM vertice_documents d
  JOIN vertice_doc_categories c ON c.code = d.category_code
  WHERE d.institution_id = p_institution_id AND d.status = 'active'
    AND d.expiry_date BETWEEN CURRENT_DATE AND CURRENT_DATE + interval '30 days'
    AND NOT EXISTS (SELECT 1 FROM vertice_doc_alerts a WHERE a.document_id = d.id AND a.alert_type = 'expiring_soon' AND NOT a.acknowledged);
  GET DIAGNOSTICS v_partial = ROW_COUNT; v_count := v_count + v_partial;

  -- Achados críticos da IA
  INSERT INTO vertice_doc_alerts (institution_id, document_id, alert_type, severity, title, message)
  SELECT f.institution_id, f.document_id, 'ai_critical', 'critical',
    'IA: problema crítico em ' || d.title, f.message
  FROM vertice_doc_findings f
  JOIN vertice_documents d ON d.id = f.document_id
  WHERE f.institution_id = p_institution_id AND f.severity = 'critical' AND NOT f.resolved
    AND NOT EXISTS (SELECT 1 FROM vertice_doc_alerts a WHERE a.document_id = f.document_id AND a.alert_type = 'ai_critical' AND NOT a.acknowledged);
  GET DIAGNOSTICS v_partial = ROW_COUNT; v_count := v_count + v_partial;

  RETURN v_count;
END $function$
;
REVOKE ALL ON FUNCTION public.generate_doc_alerts(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.generate_doc_alerts(uuid) TO service_role;
COMMIT;

